// Источник: web-тест .qa/e2e/tests/reminders/rm-03-profile-settings-consent-dialog.spec.ts, план .qa/e2e/specs/reminders.md, кейс .qa/tests/reminders/RM-03-profile-consent-names.md
// Тикет #6a86f7fa. Только чтение: окно согласия закрывается «סגירה» без сохранения.
// Пояснение «בדפדפן לא נשלחות התראות למכשיר» относится к web-сборке — в приложении не сверяется.
import { $, expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, tapLabel, expectVisibleText, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

/** Кнопка по тексту: на Android disabled стоит на кликабельном предке текста (Pressable), на iOS — на самом элементе. */
function button(text: string) {
  return driver.isAndroid
    ? $(`//*[@text="${text}"]/ancestor-or-self::*[@clickable="true"][1]`)
    : byText(text);
}

/** Нажать по тексту или по подписи доступности (кнопка-иконка «סגירה» может быть без видимого текста). */
async function tapAny(name: string) {
  const t = await byText(name);
  if (await t.isDisplayed().catch(() => false)) return t.click();
  return tapLabel(name);
}

describe('Напоминания', () => {
  afterEach(async () => { await toHome(); });

  it('RM-03 Профиль — «תזכורות והתראות» (было «תזכורות במערכת», #00542c25) и «הודעות במייל, SMS ו־WhatsApp», окно согласия #6a86f7fa @prod-safe', async () => {
    // 1. Профиль → раздел «הגדרות».
    await toHome();
    await tapLabel('מעבר לפרטים שלי');
    await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
    await scrollToText('הגדרות');
    await scrollToText('תזכורות והתראות');
    await expectTextContains('כולל התראות ל: זמני תפילה, תפילין, ספירת העומר, ראש חודש ומועדים');
    const consentRow = await byLabelStartsWith('הודעות במייל, SMS ו־WhatsApp');
    await expect(consentRow).toBeDisplayed();
    await expectTextContains('מאושר');
    for (const old of ['תזכורות במערכת', 'הסכמה לקבלת התראות', 'הסכמה נשמרה', 'לא אושרו תזכורות']) {
      await expect(byTextContains(old)).not.toBeDisplayed();
    }

    // 2. Открыть окно согласия → прочитать → «סגירה» без сохранения.
    await consentRow.click();
    await expectVisibleText('הודעות במייל, SMS ו־WhatsApp');
    const checkbox = await byLabelStartsWith('אני מאשר לקבל התראות למייל');
    await expect(checkbox).toBeDisplayed();
    if (driver.isAndroid) expect(await checkbox.getAttribute('checked')).toBe('true');
    else expect(['1', 'true']).toContain(await checkbox.getAttribute('value'));
    await expectVisibleText('אפשר לשנות את הבחירה בכל עת.');
    await expect(byTextContains('אפשר להצטרף גם בלי לאשר')).not.toBeDisplayed();
    await expect(button('שמירה')).toBeDisabled();
    await tapAny('סגירה');
    await expect(byText('אפשר לשנות את הבחירה בכל עת.')).not.toBeDisplayed();
    await expectTextContains('מאושר');
  });
});
